'use strict';
var table = require('./table.json');
function findStatus(val) {
  var start = 0;
  var end = table.length - 1;
  while (start <= end) {
    var mid = Math.floor((start + end) / 2);
    var target = table[mid];
    if (target[0][0] <= val && target[0][1] >= val) {
      return target;
    } else if (target[0][0] > val) {
      end = mid - 1;
    } else {
      start = mid + 1;
    }
  }
  return null;
}
exports.status = function (cp) {
  var found = findStatus(cp);
  return found === null ? 'unknown' : found[1];
};
exports.mapChars = function (s) {
  var error = false;
  var out = '';
  for (var i = 0; i < s.length; ++i) {
    var cp = s.codePointAt(i);
    var found = findStatus(cp);
    if (found === null) { error = true; continue; }
    switch (found[1]) {
      case 'disallowed': error = true; out += String.fromCodePoint(cp); break;
      case 'mapped': out += String.fromCodePoint.apply(String, found[2]); break;
      case 'valid': out += String.fromCodePoint(cp); break;
    }
  }
  return { text: out, error: error };
};
